#include <string.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdio.h>

#define MAX_ADDR_BUFFER 1024

bool extract_sockaddr_from_url(const char* url, char** sockaddr_url, char** sockaddr_port) {
    // Default port
    char default_port[] = "80";
    char* port = NULL;

    // Find protocol separator ('://')
    const char* proto_sep = strstr(url, "://");
    if (!proto_sep || proto_sep[0] != ':' || proto_sep[1] != '/' || proto_sep[2] != '/') {
        return false;
    }

    // Start parsing after the protocol separator
    const char* url_start = proto_sep + 3;

    // Check for bracket-enclosed IPv6 address
    if (url_start[0] == '[') {
        const char* close_bracket = strchr(url_start + 1, ']');
        if (!close_bracket) {
            return false;
        }

        size_t addr_len = close_bracket - url_start - 1;
        if (addr_len > MAX_ADDR_BUFFER) {
            fprintf(stderr, "Warning: IPv6 address exceeds buffer limit, truncating.\n");
            addr_len = MAX_ADDR_BUFFER;
        }

        *sockaddr_url = (char*)malloc(addr_len + 1);
        if (!*sockaddr_url) {
            return false;
        }

        strncpy(*sockaddr_url, url_start + 1, addr_len);
        (*sockaddr_url)[addr_len] = '\0';

        // Look for port after the closing bracket
        if (close_bracket[1] == ':') {
            port = (char*)strdup(close_bracket + 2);
            if (!port) {
                free(*sockaddr_url);
                return false;
            }
            *sockaddr_port = port;
        } else {
            *sockaddr_port = (char*)strdup(default_port);
            if (!*sockaddr_port) {
                free(*sockaddr_url);
                return false;
            }
        }
    } else {
        // Handle IPv4 or host without brackets
        const char* port_separator = strchr(url_start, ':');
        if (port_separator) {
            size_t addr_len = port_separator - url_start;
            if (addr_len > MAX_ADDR_BUFFER) {
                fprintf(stderr, "Warning: IPv4 address exceeds buffer limit, truncating.\n");
                addr_len = MAX_ADDR_BUFFER;
            }

            *sockaddr_url = (char*)malloc(addr_len + 1);
            if (!*sockaddr_url) {
                return false;
            }

            strncpy(*sockaddr_url, url_start, addr_len);
            (*sockaddr_url)[addr_len] = '\0';

            port = (char*)strdup(port_separator + 1);
            if (!port) {
                free(*sockaddr_url);
                return false;
            }
            *sockaddr_port = port;
        } else {
            size_t url_len = strlen(url_start);
            if (url_len > MAX_ADDR_BUFFER) {
                fprintf(stderr, "Warning: IPv4 address exceeds buffer limit, truncating.\n");
                url_len = MAX_ADDR_BUFFER;
            }

            *sockaddr_url = (char*)malloc(url_len + 1);
            if (!*sockaddr_url) {
                return false;
            }

            strncpy(*sockaddr_url, url_start, url_len);
            (*sockaddr_url)[url_len] = '\0';

            *sockaddr_port = (char*)strdup(default_port);
            if (!*sockaddr_port) {
                free(*sockaddr_url);
                return false;
            }
        }
    }

    return true;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_ADDR_BUFFER 1024

bool extract_sockaddr_from_url(const char* url, char** sockaddr_url, char** sockaddr_port) {
    const char* protocol_start = "://";
    const char* bracket_end = "]";
    const char* colon = ":";
    const char* default_port = "80";
    char* url_copy;
    char* protocol_pos;
    char* address;
    char* port;
    char* port_end;

    if (url == NULL || sockaddr_url == NULL || sockaddr_port == NULL) {
        return false;
    }

    url_copy = strdup(url);
    if (url_copy == NULL) {
        return false;
    }

    protocol_pos = strstr(url_copy, protocol_start);
    if (protocol_pos == NULL) {
        free(url_copy);
        return false;
    }

    address = protocol_pos + strlen(protocol_start);

    port = strstr(address, colon);
    if (port == NULL) {
        port = (char*)malloc(strlen(default_port) + 1);
        if (port == NULL) {
            free(url_copy);
            return false;
        }
        strcpy(port, default_port);
    } else {
        *port = '\0';
        port++;
        port_end = strchr(port, '/');
        if (port_end != NULL) {
            *port_end = '\0';
        }
    }

    size_t address_len = strlen(address);
    if (address_len > MAX_ADDR_BUFFER) {
        fprintf(stderr, "Warning: Socket address exceeds buffer size and will be truncated.\n");
        address_len = MAX_ADDR_BUFFER;
    }

    *sockaddr_url = (char*)malloc(address_len + 1);
    *sockaddr_port = (char*)malloc(strlen(port) + 1);

    if (*sockaddr_url == NULL || *sockaddr_port == NULL) {
        free(url_copy);
        free(port);
        free(*sockaddr_url);
        free(*sockaddr_port);
        return false;
    }

    strncpy(*sockaddr_url, address, address_len);
    (*sockaddr_url)[address_len] = '\0';
    strcpy(*sockaddr_port, port);

    free(url_copy);
    if (port != *sockaddr_port) {
        free(port);
    }

    return true;
}

#include <string.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdio.h>

#define MAX_BUFFER_SIZE 1024

bool extract_sockaddr_from_url(const char* url, char** sockaddr_url, char** sockaddr_port) {
    char buffer[MAX_BUFFER_SIZE];
    char* protocol_end;
    char* colon;
    char* bracket_end = NULL;
    int url_len;

    if (!url || !sockaddr_url || !sockaddr_port) {
        return false;
    }

    url_len = strlen(url);
    if (url_len >= MAX_BUFFER_SIZE) {
        snprintf(buffer, MAX_BUFFER_SIZE, "Warning: URL exceeds buffer size, truncating to %d characters.\n", MAX_BUFFER_SIZE - 1);
        fprintf(stderr, buffer);
        url_len = MAX_BUFFER_SIZE - 1;
    }

    strncpy(buffer, url, url_len);
    buffer[url_len] = '\0';

    // Skip the protocol (e.g., http:// or https://)
    protocol_end = buffer;
    while (*protocol_end && *protocol_end != ':' && *protocol_end != '/') {
        protocol_end++;
    }

    if (*protocol_end != ':') {
        return false; // Invalid URL format
    }

    // Skip the '://'
    protocol_end += 3;

    // Check for IPv6 (enclosed in [])
    if (*protocol_end == '[') {
        bracket_end = strchr(protocol_end, ']');
        if (!bracket_end) {
            return false; // Malformed IPv6
        }
        *bracket_end = '\0'; // Terminate the address
        colon = strchr(protocol_end + 1, ':');
        *bracket_end = ']'; // Restore the original
    } else {
        colon = strchr(protocol_end, ':');
    }

    if (!colon) {
        // No port specified, use default (80)
        *sockaddr_port = strdup("80");
        *sockaddr_url = strdup(protocol_end);
        return true;
    }

    // Extract the address
    *colon = '\0';
    *sockaddr_url = strdup(protocol_end);

    // Extract the port
    *colon = ':';
    *sockaddr_port = strdup(colon + 1);

    return true;
}

#include <string.h>
