#include <stdio.h>

#define MAX_URL_BUFFER_SIZE 1024

bool extract_sockaddr_from_url(const char* url, char** sockaddr_url, char** sockaddr_port) {
    const char* protocol_end = strstr(url, "://");
    if (!protocol_end) {
        return false;
    }

    const char* address_start = protocol_end + 3;
    const char* address_end = address_start;
    int port = 80;
    bool is_ipv6 = false;

    while (*address_end && *address_end != ':' && *address_end != '/') {
        if (*address_end == '[') {
            is_ipv6 = true;
            address_end++;
        } else if (*address_end == ']' && is_ipv6) {
            is_ipv6 = false;
            break;
        }
        address_end++;
    }

    size_t address_len = address_end - address_start;
    if (address_len > MAX_URL_BUFFER_SIZE - 1) {
        address_len = MAX_URL_BUFFER_SIZE - 1;
        fprintf(stderr, "Warning: Address truncated to fit buffer size.\n");
    }

    *sockaddr_url = (char*)malloc(address_len + 1);
    if (!*sockaddr_url) {
        return false;
    }
    strncpy(*sockaddr_url, address_start, address_len);
    (*sockaddr_url)[address_len] = '\0';

    if (*address_end == ':') {
        address_end++;
        const char* port_end = address_end;
        while (*port_end && *port_end != '/') {
            port_end++;
        }

        size_t port_len = port_end - port_end;
        if (port_len > MAX_URL_BUFFER_SIZE - 1) {
            port_len = MAX_URL_BUFFER_SIZE - 1;
        }

        *sockaddr_port = (char*)malloc(port_len + 1);
        if (!*sockaddr_port) {
            free(*sockaddr_url);
            return false;
        }
        strncpy(*sockaddr_port, port_end, port_len);
        (*sockaddr_port)[port_len] = '\0';
    } else {
        *sockaddr_port = (char*)malloc(4);
        if (!*sockaddr_port) {
            free(*sockaddr_url);
            return false;
        }
        snprintf(*sockaddr_port, 4, "%d", port);
    }

    return true;
}
